    VMCall L_BerryNewDay
    WorkSet 0x8002, VAR_BERRY_PICKED_5
    WorkAnd 0x8002, 256
    WorkCmpConst 0x8002, 0
    VMJumpIf CMP_NE, L_BerryLoamy
    VMCall L_BerryPick
    WorkCmpConst 0x8010, 1
    VMJumpIf CMP_NE, L_BerryEnd
    WorkOr VAR_BERRY_PICKED_5, 256
    FlagSet FLAG_BERRY_TREE_PICKED_79                    // the tree is gone until the next day
    WorkCmpConst 0x8012, 1
    VMJumpIf CMP_NE, L_BerryEnd
    ActorDelete 479
    VMJump L_BerryEnd

Script_293:                    // Route123 (111, 13): Sapphire tree 89
    ActorsPauseAll
    WorkSetConst 0x8000, 152       // ITEM_RAWST_BERRY
    WorkSetConst 0x8001, 2
    WorkSetConst 0x8012, 0                         // 1 = the tree stands here (its flag clear)
    VMStackPushFlag FLAG_BERRY_TREE_PICKED_80
    VMStackPushConst 0
    VMStackCmp CMP_EQ
    VMJumpIf CMP_STACK, L_BerryNoTree80     // (jumps when the comparison is false: flag set)
    WorkSetConst 0x8012, 1
L_BerryNoTree80:
    VMCall L_BerryNewDay
    WorkSet 0x8002, VAR_BERRY_PICKED_5
    WorkAnd 0x8002, 512
    WorkCmpConst 0x8002, 0
    VMJumpIf CMP_NE, L_BerryLoamy
    VMCall L_BerryPick
    WorkCmpConst 0x8010, 1
    VMJumpIf CMP_NE, L_BerryEnd
    WorkOr VAR_BERRY_PICKED_5, 512
    FlagSet FLAG_BERRY_TREE_PICKED_80                    // the tree is gone until the next day
    WorkCmpConst 0x8012, 1
    VMJumpIf CMP_NE, L_BerryEnd
    ActorDelete 480
    VMJump L_BerryEnd

L_BerryNewDay:                                  // the first pick of a day clears yesterday's picks
    VMStackPushFlag FLAG_DAILY_BERRY_SPOTS
    VMStackPushConst 0
    VMStackCmp CMP_EQ
    VMJumpIf CMP_STACK, L_BerryNewDayDone          // (jumps when the comparison is false: flag set)
    FlagSet FLAG_DAILY_BERRY_SPOTS
    WorkSetConst VAR_BERRY_PICKED_0, 0
    WorkSetConst VAR_BERRY_PICKED_1, 0
